import re
from datetime import datetime, timedelta

_MONTHS = {name: i for i, name in enumerate(
    ["JAN", "FEB", "MAR", "APR", "MAY", "JUN", "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"], 1)}
_DAYS = {name: i for i, name in enumerate(["SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT"])}

# The Gregorian calendar repeats every 400 years, so a schedule that matches nothing in that span never will.
_MAX_DAYS = 400 * 366


def _value(text: str, names: dict[str, int], lo: int, hi: int) -> int:
    if text.upper() in names:
        return names[text.upper()]
    if not re.fullmatch(r"[0-9]+", text):
        raise ValueError(f"bad cron value {text!r}")
    value = int(text)
    if not lo <= value <= hi:
        raise ValueError(f"cron value {value} out of range {lo}-{hi}")
    return value


def _field(text: str, lo: int, hi: int, star_hi: int, names: dict[str, int]) -> set[int]:
    values = set()
    for item in text.split(","):
        base, slash, step_text = item.partition("/")
        step = 1
        if slash:
            if not re.fullmatch(r"[0-9]+", step_text) or int(step_text) < 1:
                raise ValueError(f"bad cron step {step_text!r}")
            step = int(step_text)
        if base == "*":
            start, end = lo, star_hi
        else:
            start_text, dash, end_text = base.partition("-")
            start = _value(start_text, names, lo, hi)
            if dash:
                end = _value(end_text, names, lo, hi)
                if end < start:
                    raise ValueError(f"cron range {base!r} runs backwards")
            elif slash:
                raise ValueError(f"cron step needs * or a range, not {item!r}")
            else:
                end = start
        values.update(range(start, end + 1, step))
    return values


def _parse(expr: str):
    fields = expr.split(" ")
    if len(fields) != 5:
        raise ValueError(f"cron expression needs 5 fields, got {len(fields)}: {expr!r}")
    minute = _field(fields[0], 0, 59, 59, {})
    hour = _field(fields[1], 0, 23, 23, {})
    dom = _field(fields[2], 1, 31, 31, {})
    month = _field(fields[3], 1, 12, 12, _MONTHS)
    # 7 is accepted as Sunday, but a bare * means Sunday through Saturday only.
    dow = {v % 7 for v in _field(fields[4], 0, 7, 6, _DAYS)}
    return minute, hour, dom, month, dow, fields[2] != "*", fields[4] != "*"


def next_run(expr: str, after: datetime) -> datetime:
    """The first minute strictly after ``after`` (seconds and microseconds dropped first) that ``expr`` matches.

    ``expr`` has five fields separated by single spaces: minute (0-59), hour (0-23), day of month (1-31),
    month (1-12), day of week (0-6, Sunday is 0; 7 is also Sunday). Each field is ``*``, a number, a range
    ``a-b``, a step ``*/n`` or ``a-b/n``, or a comma list of those. Months may be written JAN-DEC and days of
    week SUN-SAT, in any case, also inside ranges (``MON-FRI``).

    When both day of month and day of week are restricted (neither is ``*``), a day matches when EITHER does,
    as in Vixie cron: ``0 0 13 * FRI`` fires on every 13th and on every Friday. When one of them is ``*``, only
    the other one counts. A malformed expression, or a value out of its field's range, raises ValueError.
    Times are naive: no time zones, no daylight saving.
    """
    minute, hour, dom, month, dow, dom_restricted, dow_restricted = _parse(expr)
    times = sorted(h * 60 + m for h in hour for m in minute)

    start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    day = start.date()
    for _ in range(_MAX_DAYS):
        if day.month in month:
            day_ok = day.day in dom
            dow_ok = day.isoweekday() % 7 in dow
            if dom_restricted and dow_restricted:
                matches = day_ok or dow_ok
            else:
                matches = day_ok and dow_ok
        else:
            matches = False

        if matches:
            lower = start.hour * 60 + start.minute if day == start.date() else 0
            for t in times:
                if t >= lower:
                    return datetime(day.year, day.month, day.day, t // 60, t % 60, tzinfo=start.tzinfo)
        day += timedelta(days=1)

    raise ValueError(f"cron expression never fires: {expr!r}")
